import { edit_master_checklists } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
import trashIcon from "@/assets/trash.png";
export default {
  props: {
    ChecklistItem: Object,
    deleteChecklistDialog: Boolean
  },
  data() {
    return {
      loading: false,
      trashIcon: trashIcon
    };
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    async delete_mutation() {
      this.loading = true;
      try {
        let result = await API.graphql(graphqlOperation(edit_master_checklists, {
          input: {
            checklist_id: this.ChecklistItem.checklist_id,
            checklist_status: "DEACTIVE"
          }
        }));
        var response = JSON.parse(result.data.edit_master_checklists);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.$emit("errorMsg", error.errors[0].message);
        this.loading = false;
      }
    }
  }
};
